   "id": "s15q07",
   "set": 15,
   "num": 7,
   "section": "A.2",
   "text": "The likelihood of causing interference is directly related to:",
   "options": [
    "The strength of the field from your antenna (antenna type, power and distance)",
    "The colour of the coax",
    "The time of day only",
    "The mode of the neighbour's TV"
   ],
