   "id": "c12q05",
   "chapter": 12,
   "topic": "12.2",
   "num": 5,
   "section": "A.5",
   "text": "The modulation duty cycle of CW is about:",
   "options": [
    "20%",
    "40%",
    "80%",
    "100%"
   ],
