   "topic": "12.6",
   "num": 16,
   "section": "A.5",
   "text": "In a simple CW transmitter, which stage generates the carrier?",
   "options": [
    "Buffer/driver",
    "Morse key",
    "Power amplifier",
    "Master oscillator"
   ],
   "answer": 3,
   "explanation": "The master oscillator generates the carrier at the required frequency",
